      "output": "```js\nfunction createCircuit(scene,track,samples){\nconst T=THREE,n=samples.length,L=samples[n-1].s+2,PI=Math.PI,R=Math.random;\nconst cv=(w,h,f)=>{const c=document.createElement('canvas');c.width=w;c.height=h;f(c.getContext('2d'),w,h);const t=new T.CanvasTexture(c);t.colorSpace=T.SRGBColorSpace;t.wrapS=t.wrapT=T.RepeatWrapping;t.anisotropy=8;return t};\nconst M=(c,e,i,o)=>new T.MeshStandardMaterial(Object.assign({color:c,emissive:e||0,emissiveIntensity:i||0,roughness:.5,metalness:.3},o));\nconst add=(g,m,p)=>{const o=new T.Mesh(g,m);(p||scene).add(o);return o};\nconst at=s=>samples[((Math.round(s/2)%n)+n)%n];\nconst hy=(p,o)=>p.y+o*Math.sin(p.bank||0);\nconst geo=(P,U,I)=>{const g=new T.BufferGeometry();g.setAttribute('position',new T.Float32BufferAttribute(P,3));if(U)g.setAttribute('uv',new T.Float32BufferAttribute(U,2));g.setIndex(I);g.computeVertexNormals();return g};\nconst rib=(a,b,h,v)=>{const P=[],U=[],I=[];for(let i=0;i<=n;i++){const p=samples[i%n],s=i==n?L:p.s;for(const o of[a(p),b(p)])P.push(p.x+p.nx*o,hy(p,o)+h,p.z+p.nz*o);U.push(0,s/v,1,s/v);if(i<n){const k=i*2;I.push(k,k+1,k+2,k+1,k+3,k+2)}}return geo(P,U,I)};\nconst pl=(p,o,y,g)=>g.applyMatrix4(new T.Matrix4().makeRotationY(Math.atan2(p.tx,p.tz)).setPosition(p.x+p.nx*o,hy(p,o)+y,p.z+p.nz*o));\nlet minY=1e9;samples.forEach(p=>minY=Math.min(minY,p.y));\nscene.fog=new T.FogExp2('#1b1030',.0016);\nconst lane=cv(64,256,(x,w,h)=>{x.fillStyle='#000';x.fillRect(0,0,w,h);x.fillStyle='#4a4a5a';x.fillRect(2,0,2,h);x.fillRect(w-4,0,2,h);x.fillStyle='#2e2e3a';for(const u of[w/3,2*w/3])x.fillRect(u-1,0,2,h/2)});\nadd(rib(p=>p.w,p=>-p.w,.02,16),new T.MeshStandardMaterial({color:'#0c0a16',roughness:.35,metalness:.25,emissive:'#fff',emissiveMap:lane,emissiveIntensity:.3}));\nconst k1=M('#1a0014','#ff2bd6',2),k2=M('#00141a','#00f0ff',2);\nadd(rib(p=>p.w+.9,p=>p.w,.06,4),k1);add(rib(p=>-p.w,p=>-p.w-.9,.06,4),k2);\nconst dark=M('#0d0b14',0,0,{metalness:.9,roughness:.3}),dk=[],tub=[];\nconst p0=samples[0],gw=p0.w*2+3.6;\nadd(pl(p0,0,.05,new T.BoxGeometry(p0.w*2,.04,1.2)),M('#fff','#fff',1));\nfor(const sd of[-1,1])dk.push(pl(p0,sd*(p0.w+1.5),4,new T.BoxGeometry(.6,8,.6)));\ndk.push(pl(p0,0,8.2,new T.BoxGeometry(gw,1.2,.8)));\nfor(const y of[7.55,8.85])for(const z of[-.45,.45]){const c=new T.CylinderGeometry(.07,.07,gw,6);c.rotateZ(PI/2);c.translate(0,0,z);tub.push(pl(p0,0,y,c))}\nfor(const sd of[-1,1]){const c=new T.CylinderGeometry(.07,.07,8,6);c.translate(0,0,-.35);tub.push(pl(p0,sd*(p0.w+1.5),4,c))}\nconst tubM=M('#200018','#ff2bd6',2);add(mergeGeometries(tub),tubM);\nconst arT=cv(256,96,(x,w,h)=>{x.fillStyle='#000';x.fillRect(0,0,w,h);x.strokeStyle='#fff';x.lineWidth=14;for(let i=0;i<3;i++){const o=40+i*70;x.beginPath();x.moveTo(o,14);x.lineTo(o+40,48);x.lineTo(o,82);x.stroke()}});\nconst arT2=arT.clone();arT2.repeat.x=-1;\nconst sm=[M('#05050a','#00f0ff',1.6,{emissiveMap:arT}),M('#05050a','#00f0ff',1.6,{emissiveMap:arT2})],sg=[[],[]];\n(track.signs||[]).forEach(q=>{const s=typeof q=='number'?q:(q.s??q.at??0),sd=q.side??1,dir=q.dir??-sd,p=at(s),o=sd*(p.w+3);sg[dir>0?1:0].push(pl(p,o,2.4,new T.BoxGeometry(4.5,1.6,.15)));for(const e of[-1.8,1.8])dk.push(pl(p,o+e,.8,new T.BoxGeometry(.15,1.6,.15)))});\nsg.forEach((a,i)=>a.length&&add(mergeGeometries(a),sm[i]));\nconst aA=M('#200018','#ff2bd6',1.8),aB=M('#00141a','#00f0ff',1.8),ar=[[],[]],tu=track.tunnel;\nif(tu){const a=tu.s0??tu.start??tu.from??tu[0]??0,b=tu.s1??tu.end??tu.to??tu[1]??0,len=((b-a)%L+L)%L;for(let s=0,k=0;s<=len;s+=8,k++){const p=at(a+s);ar[k%2].push(pl(p,0,0,new T.TorusGeometry(p.w+2,.18,6,32,PI)))}}\nar.forEach((a,i)=>a.length&&add(mergeGeometries(a),i?aB:aA));\nadd(mergeGeometries(dk),dark);\nconst grid=cv(128,128,(x,w)=>{x.fillStyle='#000';x.fillRect(0,0,w,w);x.fillStyle='#fff';x.fillRect(0,0,w,3);x.fillRect(0,0,3,w)});grid.repeat.set(200,200);\nconst gr=add(new T.PlaneGeometry(4000,4000),M('#06040c','#ff2bd6',1.2,{emissiveMap:grid,roughness:.6}));gr.rotation.x=-PI/2;gr.position.y=minY-.3;\nconst win=cv(64,128,(x,w,h)=>{x.fillStyle='#000';x.fillRect(0,0,w,h);for(let i=0;i<8;i++)for(let j=0;j<16;j++)if(R()<.45){x.fillStyle=`hsl(0,0%,${30+R()*50}%)`;x.fillRect(i*8+2,j*8+2,4,4)}});\n(track.towers||[]).forEach(t=>{const h=t.h||60,w=t.w||16,d=t.d||w,y0=minY-.3,u=t.hue??t.color,c=typeof u=='number'?new T.Color().setHSL(u>1?u/360:u,1,.55):new T.Color(u||'#ff2bd6');\nconst tx=win.clone();tx.repeat.set(Math.ceil(w/8),Math.ceil(h/16));\nconst m=add(new T.BoxGeometry(w,h,d),new T.MeshPhysicalMaterial({color:'#05050a',metalness:.7,roughness:.15,emissive:c,emissiveMap:tx,emissiveIntensity:1.5}));m.position.set(t.x,y0+h/2,t.z);m.rotation.y=t.rot||0;\nconst e=[];for(const a of[-1,1])for(const b of[-1,1]){e.push(new T.BoxGeometry(.35,h,.35).translate(a*w/2,0,b*d/2));e.push(new T.BoxGeometry(a>0?w:.35,.35,a>0?.35:d).translate(a>0?0:b*w/2,h/2,a>0?b*d/2:0))}\nadd(mergeGeometries(e),M('#000',c,2.5),m)});\nconst P=[],Q=[],I=[],N=120,MR=1100;\nfor(let i=0;i<=N;i++){const a=i/N*PI*2,h=70+60*Math.sin(a*5)+40*Math.sin(a*13+1)+25*Math.abs(Math.sin(a*29)),x=Math.cos(a)*MR,z=Math.sin(a)*MR;P.push(x,minY-20,z,x,h,z);Q.push(x,h-1.5,z,x,h+1.5,z);if(i<N){const k=i*2;I.push(k,k+2,k+1,k+1,k+2,k+3)}}\nadd(geo(P,null,I),M('#07040e',0,0,{side:T.DoubleSide,fog:false}));\nconst ridge=M('#000','#ff5ad0',2.2,{side:T.DoubleSide,fog:false});add(geo(Q,null,I),ridge);\nconst gt=cv(4,256,(x,w,h)=>{const g=x.createLinearGradient(0,0,0,h);[[0,'#05010f'],[.3,'#2a0a4a'],[.44,'#8a1f78'],[.5,'#ff8a3a'],[.52,'#1b1030'],[1,'#05010f']].forEach(s=>g.addColorStop(...s));x.fillStyle=g;x.fillRect(0,0,w,h)});\nconst dome=new T.Mesh(new T.SphereGeometry(3000,32,16),M('#000','#fff',1,{emissiveMap:gt,side:T.BackSide,fog:false,depthWrite:false,roughness:1,metalness:0}));dome.renderOrder=-2;\nconst sc=document.createElement('canvas');sc.width=sc.height=256;const sx=sc.getContext('2d'),st=new T.CanvasTexture(sc);st.colorSpace=T.SRGBColorSpace;\nconst drawSun=o=>{sx.globalCompositeOperation='source-over';sx.clearRect(0,0,256,256);const g=sx.createLinearGradient(0,0,0,256);g.addColorStop(0,'#ffe14a');g.addColorStop(.55,'#ff7a1a');g.addColorStop(1,'#ff2bd6');sx.fillStyle=g;sx.beginPath();sx.arc(128,128,126,0,PI*2);sx.fill();sx.globalCompositeOperation='destination-out';for(let i=0;i<8;i++){const y=128+(i*16+o)%128;sx.fillRect(0,y,256,2+(y-128)/11)}st.needsUpdate=true};drawSun(0);\nconst sun=new T.Mesh(new T.PlaneGeometry(600,600),M('#000','#fff',3,{map:st,emissiveMap:st,transparent:true,fog:false,depthWrite:false}));sun.position.set(0,180,-2700);sun.lookAt(0,180,0);sun.renderOrder=-1;\nscene.add(dome,sun);\nconst sky=new T.Scene();sky.add(dome.clone(),sun.clone());\nreturn{sky,update(t){const s=Math.sin(t*3);k1.emissiveIntensity=2+.25*s;k2.emissiveIntensity=2-.25*s;aA.emissiveIntensity=1.6+.3*Math.sin(t*4);aB.emissiveIntensity=1.6+.3*Math.cos(t*4);tubM.emissiveIntensity=1.8+.2*s;ridge.emissiveIntensity=2+.3*Math.sin(t*1.3);drawSun((t*10)%128)}};\n}\n```"
